import React, { useState, useEffect } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { toast } from 'react-toastify';
import ApiService from '../../Services/ApiService';

export default function SellerUpload() {
    const navigate = useNavigate();
    const { id } = useParams(); // Get the reel ID from the route parameter
    const [uploadData, setUploadData] = useState({
        title: '',
        description: '',
        category: '',
        video: null,
        thumbnail: null,
        associationType: '', // 'seller' or 'brand'
        selectedSeller: '',
        selectedBrand: '',
        selectedProducts: []
    });
    const [loading, setLoading] = useState(false);
    const [categories, setCategories] = useState([]);
    const [brands, setBrands] = useState([]);
    const [sellerProducts, setSellerProducts] = useState([]);
    const [brandProducts, setBrandProducts] = useState([]);
    const [relatedProducts, setRelatedProducts] = useState([]);
    const [reels, setReels] = useState([]);
    const [showUploadForm, setShowUploadForm] = useState(false);
    const [editingReelId, setEditingReelId] = useState(null);

    useEffect(() => {
        console.log('Component mounted, initializing data loading...');
        
        // Load initial data
        loadCategories();
        loadReels();
        loadBrands(); // Load brands for the brand selection
        
        // Handle route changes
        if (id) {
            // We're editing a reel
            setEditingReelId(id);
            setShowUploadForm(true);
            loadReelForEdit(id);
        } else {
            // We're on the upload page (not editing) - show list by default
            setEditingReelId(null);
            setShowUploadForm(false);
            // Reset form data only if we were previously editing
            if (editingReelId) {
                resetForm();
            }
        }
    }, [id]);
    
    // Initialize Lucide icons after render
    useEffect(() => {
        // Initialize Lucide icons
        if (window.lucide) {
            window.lucide.createIcons();
        }
        
        // Re-initialize icons when reels data changes
        const timer = setTimeout(() => {
            if (window.lucide) {
                window.lucide.createIcons();
            }
        }, 100);
        
        return () => clearTimeout(timer);
    }, [reels, showUploadForm]);

    const loadCategories = async () => {
        try {
            setLoading(true);
            const response = await ApiService.getCategories();
            if (response.success) {
                setCategories(response.data);
            } else {
                toast.error('Failed to load categories: ' + response.message);
            }
            setLoading(false);
        } catch (error) {
            console.error('Error loading categories:', error);
            toast.error('Failed to load categories: ' + error.message);
            setLoading(false);
        }
    };

    const loadReels = async () => {
        try {
            setLoading(true);
            // For sellers, we need to pass the vendor ID
            // In a real implementation, you would get this from the authenticated user
            const vendorId = 1; // This should come from the authenticated user
            const response = await ApiService.getSellerReels(vendorId);
            if (response.success) {
                setReels(response.data);
            } else {
                // Don't show error for reels loading, it's not critical
                console.log('Failed to load reels: ' + response.message);
            }
            setLoading(false);
        } catch (error) {
            console.error('Error loading reels:', error);
            // Don't show error for reels loading, it's not critical
            setLoading(false);
        }
    };

    const loadBrands = async () => {
        try {
            setLoading(true);
            const response = await ApiService.getBrands();
            if (response.success) {
                setBrands(response.data);
            } else {
                toast.error('Failed to load brands: ' + response.message);
            }
            setLoading(false);
        } catch (error) {
            console.error('Error loading brands:', error);
            toast.error('Failed to load brands: ' + error.message);
            setLoading(false);
        }
    };

    const loadSellerProducts = async (vendorId) => {
        try {
            console.log('Loading seller products for vendorId:', vendorId);
            setLoading(true);
            const response = await ApiService.getSellerProducts(vendorId);
            console.log('Seller products response:', response); // Debug log
            if (response.success) {
                setSellerProducts(response.data);
                console.log('Seller products loaded:', response.data);
            } else {
                toast.error('Failed to load seller products: ' + response.message);
                setSellerProducts([]); // Clear products on error
            }
            setLoading(false);
        } catch (error) {
            console.error('Error loading seller products:', error);
            toast.error('Failed to load seller products: ' + error.message);
            setSellerProducts([]); // Clear products on error
            setLoading(false);
        }
    };

    const loadBrandProducts = async (brandId) => {
        try {
            setLoading(true);
            const response = await ApiService.getBrandProducts(brandId);
            console.log('Brand products response:', response); // Debug log
            if (response.success) {
                setBrandProducts(response.data);
            } else {
                toast.error('Failed to load brand products: ' + response.message);
                setBrandProducts([]); // Clear products on error
            }
            setLoading(false);
        } catch (error) {
            console.error('Error loading brand products:', error);
            toast.error('Failed to load brand products: ' + error.message);
            setBrandProducts([]); // Clear products on error
            setLoading(false);
        }
    };

    // Function for fetching related products
    const loadReelForEdit = async (reelId) => {
        try {
            setLoading(true);
            const response = await ApiService.getReelById(reelId);
            
            if (response.success) {
                const reelData = response.data;
                
                // Process product IDs - they come as a comma-separated string from the backend
                let productIds = [];
                if (reelData.product_ids) {
                    if (Array.isArray(reelData.product_ids)) {
                        productIds = reelData.product_ids;
                    } else if (typeof reelData.product_ids === 'string') {
                        productIds = reelData.product_ids.split(',').map(id => parseInt(id.trim())).filter(id => !isNaN(id));
                    }
                }
                
                // Set the form data with the reel information
                setUploadData({
                    title: reelData.title || '',
                    description: reelData.description || '',
                    category: reelData.category_id || '',
                    video: null, // We don't need to preload the video file
                    thumbnail: null, // We don't need to preload the thumbnail
                    video_url: reelData.video_url || '', // Store the video URL for display
                    thumbnail_url: reelData.thumbnail || '', // Store the thumbnail URL for display
                    associationType: reelData.seller_id ? 'seller' : (reelData.brand_id ? 'brand' : ''),
                    selectedSeller: reelData.seller_id || '',
                    selectedBrand: reelData.brand_id || '',
                    selectedProducts: productIds
                });
                
                console.log('Reel loaded for edit:', reelData);
                
                // Load related data based on association type
                if (reelData.seller_id) {
                    // For sellers, we don't need to load other sellers
                    // Load seller products
                    await loadSellerProducts(reelData.seller_id);
                } else if (reelData.brand_id) {
                    // Load brand data
                    await loadBrands();
                    
                    // Load brand products
                    await loadBrandProducts(reelData.brand_id);
                }
                
                // Ensure the association type is set in state
                setUploadData(prev => ({
                    ...prev,
                    associationType: reelData.seller_id ? 'seller' : (reelData.brand_id ? 'brand' : prev.associationType)
                }));
                
                // Load related products
                if (productIds && productIds.length > 0) {
                    await loadRelatedProducts(productIds, reelData.seller_id ? 'seller' : (reelData.brand_id ? 'brand' : ''), reelData.seller_id || '', reelData.brand_id || '');
                }
            } else {
                toast.error('Failed to load reel: ' + response.message);
            }
            setLoading(false);
        } catch (error) {
            console.error('Error loading reel for edit:', error);
            toast.error('Failed to load reel: ' + error.message);
            setLoading(false);
        }
    };

    const loadRelatedProducts = async (selectedProductIds, associationType, selectedSeller, selectedBrand) => {
        try {
            setLoading(true);
            const response = await ApiService.getRelatedProducts(
                selectedProductIds,
                associationType,
                selectedSeller,
                selectedBrand
            );
            
            if (response.success) {
                setRelatedProducts(response.data);
            } else {
                // If API fails, fall back to demo implementation
                console.log('API failed, using demo implementation');
                // For demo, we'll just use some of the existing products as "related"
                let related = [];
                if (associationType === 'seller' && sellerProducts.length > 0) {
                    related = sellerProducts.filter(p => !selectedProductIds.includes(p.product_id || p.id)).slice(0, 3);
                } else if (associationType === 'brand' && brandProducts.length > 0) {
                    related = brandProducts.filter(p => !selectedProductIds.includes(p.product_id || p.id)).slice(0, 3);
                }
                
                setRelatedProducts(related);
                
                if (related.length > 0) {
                    toast.info(`Found ${related.length} related products`);
                }
            }
            setLoading(false);
        } catch (error) {
            console.error('Error loading related products:', error);
            // Fall back to demo implementation on error
            // For demo, we'll just use some of the existing products as "related"
            let related = [];
            if (associationType === 'seller' && sellerProducts.length > 0) {
                related = sellerProducts.filter(p => !selectedProductIds.includes(p.product_id || p.id)).slice(0, 3);
            } else if (associationType === 'brand' && brandProducts.length > 0) {
                related = brandProducts.filter(p => !selectedProductIds.includes(p.product_id || p.id)).slice(0, 3);
            }
            
            setRelatedProducts(related);
            setLoading(false);
            
            if (related.length > 0) {
                toast.info(`Found ${related.length} related products`);
            }
        }
    };

    const handleInputChange = (e) => {
        const { name, value } = e.target;
        setUploadData(prev => ({
            ...prev,
            [name]: value
        }));
    };

    const handleFileChange = (e, fieldName) => {
        const file = e.target.files[0];
        if (file) {
            setUploadData(prev => ({
                ...prev,
                [fieldName]: file
            }));
        }
    };

    const handleAssociationTypeChange = (type) => {
        setUploadData(prev => ({
            ...prev,
            associationType: type,
            selectedSeller: '',
            selectedBrand: '',
            selectedProducts: []
        }));
        
        // Clear products when changing association type
        setSellerProducts([]);
        setBrandProducts([]);
        setRelatedProducts([]);
        
        // Load sellers or brands based on selection
        if (type === 'seller') {
            // For sellers, we don't need to load other sellers
            // Seller products will be loaded when needed
        } else if (type === 'brand') {
            loadBrands();
        }
    };

    const handleBrandChange = (brandId) => {
        setUploadData(prev => ({
            ...prev,
            selectedBrand: brandId,
            selectedProducts: []
        }));
        
        // Clear seller products when selecting a brand
        setSellerProducts([]);
        setRelatedProducts([]);
        
        // Load brand products
        if (brandId) {
            loadBrandProducts(brandId);
        } else {
            setBrandProducts([]);
        }
    };

    const handleProductSelection = async (e) => {
        const selected = Array.from(
            e.target.selectedOptions,
            option => parseInt(option.value)
        );
        
        // Validate that max 3 products can be selected
        if (selected.length > 3) {
            toast.warn('You can select maximum 3 products');
            // Keep only the first 3 selected products
            const limitedSelection = selected.slice(0, 3);
            setUploadData(prev => ({
                ...prev,
                selectedProducts: limitedSelection
            }));
            
            // Fetch related products for the first 3 selected products
            await loadRelatedProducts(limitedSelection, uploadData.associationType, uploadData.selectedSeller, uploadData.selectedBrand);
        } else {
            setUploadData(prev => ({
                ...prev,
                selectedProducts: selected
            }));
            
            // Fetch related products when selection changes
            if (selected.length > 0) {
                await loadRelatedProducts(selected, uploadData.associationType, uploadData.selectedSeller, uploadData.selectedBrand);
            } else {
                setRelatedProducts([]);
            }
        }
    };

    const handleRelatedProductSelection = (productId) => {
        // Add related product to main selection (if not already selected and under limit)
        if (!uploadData.selectedProducts.includes(productId) && uploadData.selectedProducts.length < 3) {
            setUploadData(prev => ({
                ...prev,
                selectedProducts: [...prev.selectedProducts, productId]
            }));
        } else if (uploadData.selectedProducts.includes(productId)) {
            toast.warn('Product already selected');
        } else {
            toast.warn('You can select maximum 3 products');
        }
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        
        // Log all form data before validation
        console.log('Form data before validation:', uploadData);
        
        // More robust validation with detailed logging
        const validationDetails = {
            title: !!uploadData.title,
            category: !!uploadData.category,
            video: !!uploadData.video,
            associationType: !!uploadData.associationType,
            sellerOrBrand: (uploadData.associationType === 'seller' && !!uploadData.selectedSeller) || 
                          (uploadData.associationType === 'brand' && !!uploadData.selectedBrand),
            selectedProducts: uploadData.selectedProducts && uploadData.selectedProducts.length > 0,
            productCount: uploadData.selectedProducts ? uploadData.selectedProducts.length : 0
        };
        
        console.log('Validation details:', validationDetails);
        
        const isFormValid = 
            uploadData.title && 
            uploadData.category && 
            (editingReelId || uploadData.video) && // Video is not required when editing
            uploadData.associationType && 
            ((uploadData.associationType === 'seller' && uploadData.selectedSeller) || 
             (uploadData.associationType === 'brand' && uploadData.selectedBrand)) &&
            uploadData.selectedProducts && 
            uploadData.selectedProducts.length > 0 &&
            uploadData.selectedProducts.length <= 3;
        
        if (!isFormValid) {
            console.log('Form validation failed:', validationDetails);
            toast.error('Please fill in all required fields correctly');
            return;
        }

        setLoading(true);
        
        try {
            if (editingReelId) {
                // Edit existing reel (with optional file upload)
                if (uploadData.video || uploadData.thumbnail) {
                    // If files are selected, use FormData
                    const formData = new FormData();
                    formData.append('title', uploadData.title || '');
                    formData.append('description', uploadData.description || '');
                    formData.append('category', uploadData.category || '');
                    formData.append('associationType', uploadData.associationType || '');
                    formData.append('selectedSeller', uploadData.selectedSeller || '');
                    formData.append('selectedBrand', uploadData.selectedBrand || '');
                    formData.append('selectedProducts', JSON.stringify(uploadData.selectedProducts));
                    
                    // Add files if they exist
                    if (uploadData.video) {
                        formData.append('video', uploadData.video);
                    }
                    
                    if (uploadData.thumbnail) {
                        formData.append('thumbnail', uploadData.thumbnail);
                    }
                    
                    const response = await ApiService.editReelWithFiles(editingReelId, formData);
                    
                    if (response.success) {
                        toast.success('Reel updated successfully!');
                        // Refresh the reels list
                        await loadReels();
                        // Reset form
                        setShowUploadForm(false);
                        resetForm();
                    } else {
                        toast.error('Update failed: ' + response.message);
                    }
                } else {
                    // No files selected, use regular JSON data
                    const reelData = {
                        title: uploadData.title,
                        description: uploadData.description,
                        category: uploadData.category,
                        associationType: uploadData.associationType,
                        selectedSeller: uploadData.selectedSeller,
                        selectedBrand: uploadData.selectedBrand,
                        selectedProducts: uploadData.selectedProducts
                    };
                    
                    const response = await ApiService.editReel(editingReelId, reelData);
                    
                    if (response.success) {
                        toast.success('Reel updated successfully!');
                        // Refresh the reels list
                        await loadReels();
                        // Reset form
                        setShowUploadForm(false);
                        resetForm();
                    } else {
                        toast.error('Update failed: ' + response.message);
                    }
                }
            } else {
                // Upload new reel
                // Prepare form data for upload
                const formData = new FormData();
                console.log('=== CREATING FORM DATA ===');
                console.log('Upload data:', uploadData);
                
                // Add all fields to formData
                formData.append('title', uploadData.title || '');
                formData.append('description', uploadData.description || '');
                formData.append('category', uploadData.category || '');
                formData.append('associationType', uploadData.associationType || '');
                // For sellers, we need to specify selectedSeller as their own vendor ID
                if (uploadData.associationType === 'seller') {
                    // Use vendor ID 1 as placeholder - in real implementation, get from authenticated user
                    formData.append('selectedSeller', '1');
                } else if (uploadData.associationType === 'brand' && uploadData.selectedBrand) {
                    formData.append('selectedBrand', uploadData.selectedBrand || '');
                }
                formData.append('selectedProducts', JSON.stringify(uploadData.selectedProducts));
                
                // Add files if they exist
                if (uploadData.video) {
                    formData.append('video', uploadData.video);
                    console.log('Video file appended to formData');
                }
                
                if (uploadData.thumbnail) {
                    formData.append('thumbnail', uploadData.thumbnail);
                    console.log('Thumbnail file appended to formData');
                } else {
                    console.log('No thumbnail file to append');
                }
                
                console.log('FormData contents:');
                for (let [key, value] of formData.entries()) {
                    console.log(key, value);
                }
                
                console.log('Sending upload request with data:', uploadData);
                
                const response = await ApiService.uploadSellerReel(formData);
                
                if (response.success) {
                    toast.success('Reel uploaded successfully!');
                    // Refresh the reels list
                    await loadReels();
                    setShowUploadForm(false);
                    resetForm();
                } else {
                    toast.error('Upload failed: ' + response.message);
                }
            }
            setLoading(false);
        } catch (error) {
            console.error('Upload error:', error);
            // Show more specific error message
            const errorMessage = error.message || 'Unknown error occurred';
            toast.error('Upload failed: ' + errorMessage);
            setLoading(false);
        }
    };

    const resetForm = () => {
        setUploadData({
            title: '',
            description: '',
            category: '',
            video: null,
            thumbnail: null,
            video_url: '',
            thumbnail_url: '',
            associationType: '',
            selectedSeller: '',
            selectedBrand: '',
            selectedProducts: []
        });
        setSellerProducts([]);
        setBrandProducts([]);
        setRelatedProducts([]);
        setEditingReelId(null);
    };

    const getStatusBadge = (status) => {
        switch (status) {
            case 'approved':
                return <span className="badge bg-success">Approved</span>;
            case 'pending':
                return <span className="badge bg-warning">Pending</span>;
            case 'rejected':
                return <span className="badge bg-danger">Rejected</span>;
            default:
                return <span className="badge bg-secondary">Unknown</span>;
        }
    };

    return (
        <div className="row">
            <div className="col-12">
                <div className="page-title-box d-flex align-items-center justify-content-between">
                    <h4 className="page-title mb-0">Reels Management</h4>
                </div>
            </div>

            <div className="col-12">
                <div className="card">
                    <div className="card-header d-flex align-items-center justify-content-between">
                        <h5 className="card-title mb-0">Uploaded Reels</h5>
                        <button 
                            className="btn btn-success" 
                            onClick={() => setShowUploadForm(!showUploadForm)}
                        >
                            <i className="ri-add-line me-1"></i>
                            {showUploadForm ? 'Cancel' : 'Add Reel'}
                        </button>
                    </div>
                    <div className="card-body">
                        {showUploadForm ? (
                            <form onSubmit={handleSubmit}>
                                <div className="row">
                                    <div className="col-md-8">
                                        <div className="mb-3">
                                            <label htmlFor="title" className="form-label">
                                                Title <span className="text-danger">*</span>
                                            </label>
                                            <input
                                                type="text"
                                                className="form-control"
                                                id="title"
                                                name="title"
                                                placeholder="Enter reel title"
                                                value={uploadData.title}
                                                onChange={handleInputChange}
                                                disabled={loading}
                                                required
                                            />
                                        </div>

                                        <div className="mb-3">
                                            <label htmlFor="description" className="form-label">
                                                Description
                                            </label>
                                            <textarea
                                                className="form-control"
                                                id="description"
                                                name="description"
                                                rows="4"
                                                placeholder="Enter reel description"
                                                value={uploadData.description}
                                                onChange={handleInputChange}
                                                disabled={loading}
                                            ></textarea>
                                        </div>

                                        <div className="mb-3">
                                            <label htmlFor="category" className="form-label">
                                                Category <span className="text-danger">*</span>
                                            </label>
                                            <select
                                                className="form-select"
                                                id="category"
                                                name="category"
                                                value={uploadData.category}
                                                onChange={handleInputChange}
                                                disabled={loading}
                                                required
                                            >
                                                <option value="">Select a category</option>
                                                {categories.map(category => (
                                                    <option key={category.id} value={category.id}>
                                                        {category.name}
                                                    </option>
                                                ))}
                                            </select>
                                        </div>

                                        {/* Association Type Selection - Appears after category is selected */}
                                        {uploadData.category && (
                                            <div className="mb-3">
                                                <label className="form-label">
                                                    Associate With <span className="text-danger">*</span>
                                                </label>
                                                <div className="d-flex gap-3">
                                                    <div className="form-check">
                                                        <input
                                                            className="form-check-input"
                                                            type="radio"
                                                            name="associationType"
                                                            id="associateProduct"
                                                            value="product"
                                                            checked={uploadData.associationType === 'product'}
                                                            onChange={() => handleAssociationTypeChange('product')}
                                                            disabled={loading}
                                                        />
                                                        <label className="form-check-label" htmlFor="associateProduct">
                                                            Product
                                                        </label>
                                                    </div>
                                                    <div className="form-check">
                                                        <input
                                                            className="form-check-input"
                                                            type="radio"
                                                            name="associationType"
                                                            id="associateBrand"
                                                            value="brand"
                                                            checked={uploadData.associationType === 'brand'}
                                                            onChange={() => handleAssociationTypeChange('brand')}
                                                            disabled={loading}
                                                        />
                                                        <label className="form-check-label" htmlFor="associateBrand">
                                                            Brand
                                                        </label>
                                                    </div>
                                                </div>
                                            </div>
                                        )}

                                        {/* Brand Selection - Appears when brand association is selected */}
                                        {uploadData.associationType === 'brand' && (
                                            <div className="mb-3">
                                                <label htmlFor="selectedBrand" className="form-label">
                                                    Select Brand <span className="text-danger">*</span>
                                                </label>
                                                <select
                                                    className="form-select"
                                                    id="selectedBrand"
                                                    name="selectedBrand"
                                                    value={uploadData.selectedBrand}
                                                    onChange={(e) => handleBrandChange(e.target.value)}
                                                    disabled={loading}
                                                    required
                                                >
                                                    <option value="">Select a brand</option>
                                                    {brands.map(brand => (
                                                        <option key={brand.id} value={brand.id}>
                                                            {brand.name}
                                                        </option>
                                                    ))}
                                                </select>
                                            </div>
                                        )}

                                        {/* Product Selection - Appears based on association type */}
                                        {(uploadData.associationType === 'product' && sellerProducts.length > 0) || 
                                         (uploadData.associationType === 'brand' && uploadData.selectedBrand && brandProducts.length > 0) ? (
                                            <div className="mb-3">
                                                <label className="form-label">
                                                    Select Product <span className="text-danger">*</span>
                                                </label>
                                                <select
                                                    className="form-select"
                                                    name="selectedProduct"
                                                    value={uploadData.selectedProduct}
                                                    onChange={handleInputChange}
                                                    disabled={loading}
                                                    required
                                                >
                                                    <option value="">Select a product</option>
                                                    {uploadData.associationType === 'product' 
                                                        ? sellerProducts.map(product => (
                                                            <option 
                                                                key={product.product_id} 
                                                                value={product.product_id}
                                                            >
                                                                {product.name} ({product.model})
                                                            </option>
                                                        ))
                                                        : brandProducts.map(product => (
                                                            <option 
                                                                key={product.id} 
                                                                value={product.id}
                                                            >
                                                                {product.name} ({product.model})
                                                            </option>
                                                        ))
                                                    }
                                                </select>
                                            </div>
                                        ) : uploadData.associationType === 'product' && uploadData.category ? (
                                            <div className="mb-3">
                                                <button 
                                                    type="button" 
                                                    className="btn btn-outline-primary"
                                                    onClick={loadSellerProducts}
                                                    disabled={loading}
                                                >
                                                    {loading ? 'Loading...' : 'Load My Products'}
                                                </button>
                                            </div>
                                        ) : null}

                                        {/* Related Products Section - Appears when a product is selected */}
                                        {relatedProducts.length > 0 && (
                                            <div className="mb-3">
                                                <label className="form-label">Related Products</label>
                                                <div className="row">
                                                    {relatedProducts.map(product => (
                                                        <div className="col-md-6 mb-2" key={product.product_id || product.id}>
                                                            <div className="card h-100">
                                                                <div className="card-body">
                                                                    <h6 className="card-title">{product.name}</h6>
                                                                    <p className="card-text text-muted small mb-2">
                                                                        {product.model || 'No model info'}
                                                                    </p>
                                                                    <button
                                                                        type="button"
                                                                        className="btn btn-sm btn-outline-primary w-100"
                                                                        onClick={() => handleRelatedProductSelection(product.product_id || product.id)}
                                                                    >
                                                                        Use This Product
                                                                    </button>
                                                                </div>
                                                            </div>
                                                        </div>
                                                    ))}
                                                </div>
                                            </div>
                                        )}
                                    </div>

                                    <div className="col-md-4">
                                        <div className="mb-3">
                                            <label className="form-label">
                                                Video <span className="text-danger">*</span>
                                            </label>
                                            <div className="input-group">
                                                <input
                                                    type="file"
                                                    className="form-control"
                                                    accept="video/*"
                                                    onChange={(e) => handleFileChange(e, 'video')}
                                                    disabled={loading}
                                                    required
                                                />
                                            </div>
                                            <div className="form-text">
                                                MP4, MOV, AVI formats allowed. Max size: 100MB
                                            </div>
                                        </div>

                                        <div className="mb-3">
                                            <label className="form-label">
                                                Thumbnail
                                            </label>
                                            <div className="input-group">
                                                <input
                                                    type="file"
                                                    className="form-control"
                                                    accept="image/*"
                                                    onChange={(e) => handleFileChange(e, 'thumbnail')}
                                                    disabled={loading}
                                                />
                                            </div>
                                            <div className="form-text">
                                                JPG, PNG formats allowed. Recommended size: 1280x720
                                            </div>
                                        </div>
                                    </div>
                                </div>

                                <div className="d-flex gap-2">
                                    <button
                                        type="button"
                                        className="btn btn-secondary"
                                        onClick={() => setShowUploadForm(false)}
                                        disabled={loading}
                                    >
                                        Cancel
                                    </button>
                                    <button
                                        type="submit"
                                        className="btn btn-success"
                                        disabled={loading}
                                    >
                                        {loading ? (
                                            <>
                                                <span className="spinner-border spinner-border-sm me-2" role="status" aria-hidden="true"></span>
                                                Uploading...
                                            </>
                                        ) : (
                                            <>
                                                <i className="ri-upload-line me-1"></i> Upload Reel
                                            </>
                                        )}
                                    </button>
                                </div>
                            </form>
                        ) : (
                            <>
                                {loading ? (
                                    <div className="text-center py-5">
                                        <div className="spinner-border" role="status">
                                            <span className="visually-hidden">Loading...</span>
                                        </div>
                                    </div>
                                ) : reels.length === 0 ? (
                                    <div className="text-center py-5">
                                        <h5>No reels found</h5>
                                        <p className="text-muted">Upload your first reel to get started.</p>
                                    </div>
                                ) : (
                                    <div className="table-responsive">
                                        <table className="table table-hover align-middle mb-0">
                                            <thead>
                                                <tr>
                                                    <th>Title</th>
                                                    <th>Category</th>
                                                    <th>Status</th>
                                                    <th>Views</th>
                                                    <th>Likes</th>
                                                    <th>Date</th>
                                                    <th>Actions</th>
                                                </tr>
                                            </thead>
                                            <tbody>
                                                {reels.map((reel) => (
                                                    <tr key={reel.id}>
                                                        <td>{reel.title}</td>
                                                        <td>{reel.category_name}</td>
                                                        <td>{getStatusBadge(reel.status)}</td>
                                                        <td>{reel.views}</td>
                                                        <td>{reel.likes}</td>
                                                        <td>{new Date(reel.created_at).toLocaleDateString()}</td>
                                                        <td>
                                                            <button className="btn btn-sm btn-soft-info me-1">
                                                                <i className="ri-eye-line"></i>
                                                            </button>
                                                            <button className="btn btn-sm btn-soft-warning me-1">
                                                                <i className="ri-edit-line"></i>
                                                            </button>
                                                            <button className="btn btn-sm btn-soft-danger">
                                                                <i className="ri-delete-bin-line"></i>
                                                            </button>
                                                        </td>
                                                    </tr>
                                                ))}
                                            </tbody>
                                        </table>
                                    </div>
                                )}
                            </>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
}
